<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Auth,Csrf,Database,View};
use App\Services\VentaService;

final class VentasController
{
 public function pos():void {Auth::requireLogin();$db=Database::connection();$productos=$db->query("SELECT m.id,m.codigo,m.nombre,m.concentracion,m.presentacion,m.precio_venta,m.imagen,COALESCE(SUM(CASE WHEN l.estado='habilitado' AND l.fecha_vencimiento>CURDATE() THEN l.cantidad_disponible ELSE 0 END),0) stock FROM medicamentos m LEFT JOIN lotes l ON l.medicamento_id=m.id WHERE m.activo=1 GROUP BY m.id HAVING stock>0 ORDER BY m.nombre")->fetchAll();View::render('ventas/pos',compact('productos'));}
 public function stockCheck():void {Auth::requireLogin();Csrf::enforce();header('Content-Type: application/json; charset=UTF-8');$items=json_decode($_POST['items']??'[]',true);if(!is_array($items)||!$items){http_response_code(422);echo json_encode(['ok'=>false,'message'=>'El carrito está vacío.']);return;}$db=Database::connection();$q=$db->prepare("SELECT m.nombre,COALESCE(SUM(CASE WHEN l.estado='habilitado' AND l.fecha_vencimiento>CURDATE() THEN l.cantidad_disponible ELSE 0 END),0) stock FROM medicamentos m LEFT JOIN lotes l ON l.medicamento_id=m.id WHERE m.id=? AND m.activo=1 GROUP BY m.id");$result=[];$ok=true;foreach($items as$item){$id=filter_var($item['medicamento_id']??null,FILTER_VALIDATE_INT);$requested=filter_var($item['cantidad']??null,FILTER_VALIDATE_INT);if(!$id||!$requested||$requested<1){$ok=false;continue;}$q->execute([$id]);$row=$q->fetch();$available=(int)($row['stock']??0);$valid=$row&&$available>=$requested;if(!$valid)$ok=false;$result[]=['medicamento_id'=>(int)$id,'nombre'=>$row['nombre']??'Producto no disponible','solicitado'=>(int)$requested,'disponible'=>$available,'valido'=>(bool)$valid];}echo json_encode(['ok'=>$ok,'items'=>$result,'message'=>$ok?'Stock confirmado.':'Uno o más productos ya no tienen stock suficiente.'],JSON_UNESCAPED_UNICODE);}
 public function save():void {Auth::requireLogin();Csrf::enforce();$raw=$_POST['items']??'[]';$items=json_decode($raw,true);if(!is_array($items))$items=[];try{$id=(new VentaService())->registrar($items,Auth::id(),$_POST);flash('success','Venta registrada correctamente.');redirect('index.php?page=venta&id='.$id);}catch(\Throwable $e){flash('danger',$e->getMessage());redirect('index.php?page=ventas');}}
 public function historial():void {Auth::requireLogin();$db=Database::connection();$desde=$_GET['desde']??'';$hasta=$_GET['hasta']??'';$q=trim($_GET['q']??'');$sql='SELECT v.*,u.nombres usuario,COUNT(d.id) items FROM ventas v JOIN usuarios u ON u.id=v.usuario_id LEFT JOIN detalle_ventas d ON d.venta_id=v.id WHERE 1';$p=[];if($desde){$sql.=' AND DATE(v.creado_en)>=?';$p[]=$desde;}if($hasta){$sql.=' AND DATE(v.creado_en)<=?';$p[]=$hasta;}if($q!==''){$sql.=' AND (v.numero LIKE ? OR v.cliente_nombre LIKE ?)';$x="%$q%";array_push($p,$x,$x);}$sql.=' GROUP BY v.id ORDER BY v.id DESC LIMIT 500';$s=$db->prepare($sql);$s->execute($p);$ventas=$s->fetchAll();View::render('ventas/historial',compact('ventas','desde','hasta','q'));}
 public function show():void {Auth::requireLogin();$db=Database::connection();$id=(int)($_GET['id']??0);$s=$db->prepare('SELECT v.*,u.nombres usuario FROM ventas v JOIN usuarios u ON u.id=v.usuario_id WHERE v.id=?');$s->execute([$id]);$venta=$s->fetch();if(!$venta){http_response_code(404);exit('Venta no encontrada');}$s=$db->prepare("SELECT d.*,m.codigo,m.nombre,GROUP_CONCAT(CONCAT(l.numero_lote,' (',dvl.cantidad,')') ORDER BY l.fecha_vencimiento SEPARATOR ', ') lotes FROM detalle_ventas d JOIN medicamentos m ON m.id=d.medicamento_id JOIN detalle_venta_lotes dvl ON dvl.detalle_venta_id=d.id JOIN lotes l ON l.id=dvl.lote_id WHERE d.venta_id=? GROUP BY d.id");$s->execute([$id]);$detalles=$s->fetchAll();if(($_GET['modal']??'')==='1'){require BASE_PATH.'/app/Views/ventas/receipt.php';return;}View::render('ventas/show',compact('venta','detalles'));}
}
